CREATE OR REPLACE PROCEDURE backfill_advisor_username_from_person()
LANGUAGE plpgsql
AS $$
DECLARE
  r RECORD;
  primary_mobile TEXT;
  chosen_username TEXT;
BEGIN
  -- 2. person_id has username in n_user -> set a.username
  UPDATE n_advisor a
  SET username = (SELECT u.username FROM n_user u WHERE u.person_id = a.person_id LIMIT 1)
  WHERE a.person_id IS NOT NULL AND a.username IS NULL
    AND EXISTS (SELECT 1 FROM n_user u WHERE u.person_id = a.person_id);

  -- 3. person has no user: use person's primary number as a.username and u.username (create user)
  FOR r IN (
    SELECT DISTINCT a.person_id AS pid FROM n_advisor a
    WHERE a.person_id IS NOT NULL AND a.username IS NULL
      AND NOT EXISTS (SELECT 1 FROM n_user u WHERE u.person_id = a.person_id)
  )
  LOOP
    primary_mobile := (
      SELECT (jsonb_path_query_first(COALESCE(p.mobile_numbers, '[]'::jsonb), '$[*] ? (@.isPrimary == true)') ->> 'number')
      FROM n_person p WHERE p.id = r.pid
    );
    chosen_username := NULLIF(TRIM(COALESCE(primary_mobile, '')), '');
    INSERT INTO n_user (person_id, username, status, created_by, created_at, updated_by, updated_at, version)
    VALUES (r.pid, chosen_username, 'ACTIVE', 'migration', CURRENT_TIMESTAMP, 'migration', CURRENT_TIMESTAMP, 0);
    UPDATE n_advisor SET username = chosen_username WHERE person_id = r.pid;
  END LOOP;
END;
$$;
/
